import copy


class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    # Deep copy the document to ensure immutability of input and no shared mutable objects
    current = copy.deepcopy(doc)

    for op_dict in ops:
        if not isinstance(op_dict, dict):
            raise PatchError("Each op must be a dict")

        op = op_dict.get("op")
        path = op_dict.get("path")

        if op is None:
            raise PatchError("Missing 'op'")
        if path is None:
            raise PatchError("Missing 'path'")

        if op in ("add", "replace", "test"):
            if "value" not in op_dict:
                raise PatchError(f"Missing 'value' for op '{op}'")
            value = op_dict["value"]
        elif op in ("move", "copy"):
            if "from" not in op_dict:
                raise PatchError(f"Missing 'from' for op '{op}'")
            from_path = op_dict["from"]
        else:
            raise PatchError(f"Unknown op '{op}'")

        if op == "add":
            current = _apply_add(current, path, value)
        elif op == "remove":
            current = _apply_remove(current, path)
        elif op == "replace":
            current = _apply_replace(current, path, value)
        elif op == "move":
            current = _apply_move(current, path, from_path)
        elif op == "copy":
            current = _apply_copy(current, path, from_path)
        elif op == "test":
            current = _apply_test(current, path, value)
        else:
            raise PatchError(f"Unknown op '{op}'")

    return current


def _parse_pointer(path):
    """Parse a JSON Pointer string into a list of tokens."""
    if path == "":
        return []
    if not path.startswith("/"):
        raise PatchError(f"Invalid path: {path}")

    tokens = path[1:].split("/")
    parsed = []
    for token in tokens:
        # Validate and decode the token
        i = 0
        valid_token = []
        while i < len(token):
            if token[i] == '~':
                if i + 1 < len(token) and token[i+1] in ('0', '1'):
                    if token[i+1] == '1':
                        valid_token.append('/')
                    else:
                        valid_token.append('~')
                    i += 2
                else:
                    raise PatchError(f"Invalid escape in path token: {token}")
            else:
                valid_token.append(token[i])
                i += 1
        parsed.append("".join(valid_token))

    return parsed


def _get_parent_and_key(doc, tokens):
    """Traverse to the parent of the target, returning (parent, key).
    If tokens is empty, returns (None, None) indicating the root."""
    if not tokens:
        return None, None

    current = doc
    for i, token in enumerate(tokens[:-1]):
        if isinstance(current, dict):
            if token not in current:
                raise PatchError(f"Key '{token}' not found")
            current = current[token]
        elif isinstance(current, list):
            try:
                idx = int(token)
            except ValueError:
                raise PatchError(f"Invalid list index: {token}")
            if idx < 0 or idx >= len(current):
                raise PatchError(f"List index {idx} out of range")
            current = current[idx]
        else:
            raise PatchError(f"Cannot traverse into non-container")

    last_token = tokens[-1]
    return current, last_token


def _apply_add(doc, path, value):
    tokens = _parse_pointer(path)

    if not tokens:
        # Adding at "" replaces the whole document
        return value

    parent, key = _get_parent_and_key(doc, tokens)

    if parent is None:
        raise PatchError("Internal error")

    if isinstance(parent, dict):
        parent[key] = value
    elif isinstance(parent, list):
        try:
            idx = int(key)
        except ValueError:
            raise PatchError(f"Invalid list index: {key}")

        if key == "-":
            parent.append(value)
        else:
            if idx < 0 or idx > len(parent):
                raise PatchError(f"List index {idx} out of range for add")
            parent.insert(idx, value)
    else:
        raise PatchError("Parent is not a container")

    return doc


def _apply_remove(doc, path):
    tokens = _parse_pointer(path)

    if not tokens:
        raise PatchError("Cannot remove root document")

    parent, key = _get_parent_and_key(doc, tokens)

    if isinstance(parent, dict):
        if key not in parent:
            raise PatchError(f"Key '{key}' not found for removal")
        del parent[key]
    elif isinstance(parent, list):
        try:
            idx = int(key)
        except ValueError:
            raise PatchError(f"Invalid list index: {key}")
        if idx < 0 or idx >= len(parent):
            raise PatchError(f"List index {idx} out of range for removal")
        del parent[idx]
    else:
        raise PatchError("Parent is not a container")

    return doc


def _apply_replace(doc, path, value):
    tokens = _parse_pointer(path)

    if not tokens:
        # Replace root
        return value

    parent, key = _get_parent_and_key(doc, tokens)

    if isinstance(parent, dict):
        if key not in parent:
            raise PatchError(f"Key '{key}' not found for replacement")
        parent[key] = value
    elif isinstance(parent, list):
        try:
            idx = int(key)
        except ValueError:
            raise PatchError(f"Invalid list index: {key}")
        if idx < 0 or idx >= len(parent):
            raise PatchError(f"List index {idx} out of range for replacement")
        parent[idx] = value
    else:
        raise PatchError("Parent is not a container")

    return doc


def _apply_move(doc, path, from_path):
    # Check if path is a proper descendant of from_path
    from_tokens = _parse_pointer(from_path)
    to_tokens = _parse_pointer(path)

    # Check if to_tokens is a proper descendant of from_tokens
    # i.e., from_tokens is a prefix of to_tokens and len(to_tokens) > len(from_tokens)
    if len(to_tokens) > len(from_tokens):
        if to_tokens[:len(from_tokens)] == from_tokens:
            raise PatchError("Cannot move to a proper descendant of the source")

    # Get the value at from_path
    if not from_tokens:
        raise PatchError("Cannot move from root")

    parent_from, key_from = _get_parent_and_key(doc, from_tokens)

    if isinstance(parent_from, dict):
        if key_from not in parent_from:
            raise PatchError(f"Key '{key_from}' not found at 'from'")
        value = parent_from[key_from]
        del parent_from[key_from]
    elif isinstance(parent_from, list):
        try:
            idx_from = int(key_from)
        except ValueError:
            raise PatchError(f"Invalid list index: {key_from}")
        if idx_from < 0 or idx_from >= len(parent_from):
            raise PatchError(f"List index {idx_from} out of range for 'from'")
        value = parent_from[idx_from]
        del parent_from[idx_from]
    else:
        raise PatchError("Parent at 'from' is not a container")

    # Now add the value at path
    # We need to re-traverse because the document has changed
    if not to_tokens:
        # Adding to root? No, move to root is not allowed unless from is also root, which is a no-op.
        # But from == path is a no-op.
        if from_tokens == to_tokens:
            return doc
        raise PatchError("Cannot move to root")

    # Re-traverse to the parent of the target path
    if len(to_tokens) == 1:
        # Parent is root
        parent_to = doc
        key_to = to_tokens[0]
    else:
        # Traverse to the parent
        current = doc
        for token in to_tokens[:-1]:
            if isinstance(current, dict):
                if token not in current:
                    raise PatchError(f"Key '{token}' not found during move traversal")
                current = current[token]
            elif isinstance(current, list):
                try:
                    idx = int(token)
                except ValueError:
                    raise PatchError(f"Invalid list index: {token}")
                if idx < 0 or idx >= len(current):
                    raise PatchError(f"List index {idx} out of range during move traversal")
                current = current[idx]
            else:
                raise PatchError("Cannot traverse into non-container")
        parent_to = current
        key_to = to_tokens[-1]

    if isinstance(parent_to, dict):
        parent_to[key_to] = value
    elif isinstance(parent_to, list):
        try:
            idx_to = int(key_to)
        except ValueError:
            raise PatchError(f"Invalid list index: {key_to}")

        if key_to == "-":
            parent_to.append(value)
        else:
            if idx_to < 0 or idx_to > len(parent_to):
                raise PatchError(f"List index {idx_to} out of range for move target")
            parent_to.insert(idx_to, value)
    else:
        raise PatchError("Parent at 'path' is not a container")

    return doc


def _apply_copy(doc, path, from_path):
    # Get the value at from_path
    from_tokens = _parse_pointer(from_path)

    if not from_tokens:
        raise PatchError("Cannot copy from root")

    parent_from, key_from = _get_parent_and_key(doc, from_tokens)

    if isinstance(parent_from, dict):
        if key_from not in parent_from:
            raise PatchError(f"Key '{key_from}' not found at 'from'")
        value = copy.deepcopy(parent_from[key_from])
    elif isinstance(parent_from, list):
        try:
            idx_from = int(key_from)
        except ValueError:
            raise PatchError(f"Invalid list index: {key_from}")
        if idx_from < 0 or idx_from >= len(parent_from):
            raise PatchError(f"List index {idx_from} out of range for 'from'")
        value = copy.deepcopy(parent_from[idx_from])
    else:
        raise PatchError("Parent at 'from' is not a container")

    # Now add the value at path
    to_tokens = _parse_pointer(path)

    if not to_tokens:
        raise PatchError("Cannot copy to root")

    # Re-traverse to the parent of the target path
    if len(to_tokens) == 1:
        parent_to = doc
        key_to = to_tokens[0]
    else:
        current = doc
        for token in to_tokens[:-1]:
            if isinstance(current, dict):
                if token not in current:
                    raise PatchError(f"Key '{token}' not found during copy traversal")
                current = current[token]
            elif isinstance(current, list):
                try:
                    idx = int(token)
                except ValueError:
                    raise PatchError(f"Invalid list index: {token}")
                if idx < 0 or idx >= len(current):
                    raise PatchError(f"List index {idx} out of range during copy traversal")
                current = current[idx]
            else:
                raise PatchError("Cannot traverse into non-container")
        parent_to = current
        key_to = to_tokens[-1]

    if isinstance(parent_to, dict):
        parent_to[key_to] = value
    elif isinstance(parent_to, list):
        try:
            idx_to = int(key_to)
        except ValueError:
            raise PatchError(f"Invalid list index: {key_to}")

        if key_to == "-":
            parent_to.append(value)
        else:
            if idx_to < 0 or idx_to > len(parent_to):
                raise PatchError(f"List index {idx_to} out of range for copy target")
            parent_to.insert(idx_to, value)
    else:
        raise PatchError("Parent at 'path' is not a container")

    return doc


def _apply_test(doc, path, value):
    tokens = _parse_pointer(path)

    if not tokens:
        # Test against the whole document
        if not _json_equal(doc, value):
            raise PatchError("Test failed: root document does not match value")
        return doc

    parent, key = _get_parent_and_key(doc, tokens)

    if isinstance(parent, dict):
        if key not in parent:
            raise PatchError(f"Key '{key}' not found for test")
        target = parent[key]
    elif isinstance(parent, list):
        try:
            idx = int(key)
        except ValueError:
            raise PatchError(f"Invalid list index: {key}")
        if idx < 0 or idx >= len(parent):
            raise PatchError(f"List index {idx} out of range for test")
        target = parent[idx]
    else:
        raise PatchError("Parent is not a container")

    if not _json_equal(target, value):
        raise PatchError("Test failed: target does not match value")

    return doc


def _json_equal(a, b):
    """Check JSON equality."""
    if type(a) != type(b):
        # Special case: numbers
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            # Booleans are a subclass of int in Python, so check for bool first
            if isinstance(a, bool) or isinstance(b, bool):
                return False
            return a == b
        return False

    if isinstance(a, bool):
        return a == b
    if isinstance(a, (int, float)):
        return a == b
    if isinstance(a, str):
        return a == b
    if isinstance(a, list):
        if len(a) != len(b):
            return False
        return all(_json_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(_json_equal(a[k], b[k]) for k in a)
    if a is None:
        return b is None
    return False

