def glob_match(pattern, path):
    r"""Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    # Parse the pattern into segments separated by '/'
    # We need to handle escaped characters and character classes

    def parse_pattern(pattern):
        """Parse pattern into a list of segments. Each segment is a list of tokens."""
        segments = []
        current_segment = []
        i = 0
        n = len(pattern)

        while i < n:
            c = pattern[i]
            if c == '\\':
                if i + 1 >= n:
                    raise ValueError("Trailing lone backslash in pattern")
                i += 1
                current_segment.append(('literal', pattern[i]))
                i += 1
            elif c == '[':
                # Parse character class
                i += 1
                negated = False
                if i < n and pattern[i] == '!':
                    negated = True
                    i += 1
                elif i < n and pattern[i] == '^':
                    negated = True
                    i += 1

                chars = set()
                # A ] right after [ or [! is a literal
                if i < n and pattern[i] == ']':
                    chars.add(']')
                    i += 1

                while i < n and pattern[i] != ']':
                    if pattern[i] == '\\' and i + 1 < n:
                        # Backslash in set is literal per spec
                        chars.add(pattern[i])
                        chars.add(pattern[i + 1])
                        i += 2
                    elif i + 2 < n and pattern[i + 1] == '-' and pattern[i + 2] != ']':
                        # Range
                        start = pattern[i]
                        end = pattern[i + 2]
                        for code in range(ord(start), ord(end) + 1):
                            chars.add(chr(code))
                        i += 3
                    else:
                        chars.add(pattern[i])
                        i += 1

                if i >= n:
                    raise ValueError("Unterminated [ in pattern")

                # Skip the closing ]
                i += 1
                current_segment.append(('char_class', chars, negated))
            elif c == '/':
                segments.append(current_segment)
                current_segment = []
                i += 1
            elif c == '*':
                current_segment.append(('any_string',))
                i += 1
            elif c == '?':
                current_segment.append(('any_char',))
                i += 1
            else:
                current_segment.append(('literal', c))
                i += 1

        segments.append(current_segment)
        return segments

    def process_segments(segments):
        """Process segments to handle ** specially."""
        processed = []
        for seg in segments:
            # Check if segment is exactly **
            if len(seg) == 2 and seg[0] == ('any_string',) and seg[1] == ('any_string',):
                processed.append(('star_star',))
            else:
                processed.append(('segment', seg))
        return processed

    def match_segment(seg_tokens, path_seg):
        """Match a segment's tokens against a path segment string."""
        m = len(seg_tokens)
        n = len(path_seg)

        # dp[i][j] = True if seg_tokens[:i] matches path_seg[:j]
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = True

        for i in range(1, m + 1):
            token = seg_tokens[i - 1]
            if token[0] == 'any_string':
                # * matches zero or more chars (not '/')
                for j in range(n + 1):
                    if j > 0 and path_seg[j - 1] != '/':
                        dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
                    else:
                        dp[i][j] = dp[i - 1][j]
            else:
                for j in range(1, n + 1):
                    if token[0] == 'literal':
                        if path_seg[j - 1] == token[1]:
                            dp[i][j] = dp[i - 1][j - 1]
                    elif token[0] == 'any_char':
                        if path_seg[j - 1] != '/':
                            dp[i][j] = dp[i - 1][j - 1]
                    elif token[0] == 'char_class':
                        chars, negated = token[1], token[2]
                        c = path_seg[j - 1]
                        if c != '/' and (c in chars) != negated:
                            dp[i][j] = dp[i - 1][j - 1]

        return dp[m][n]

    # Parse and process pattern
    segments = parse_pattern(pattern)
    processed_segments = process_segments(segments)

    # Split path into segments
    path_segments = path.split('/') if path else []

    # Use memoized recursion to match
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(seg_idx, path_idx):
        if seg_idx == len(processed_segments):
            return path_idx == len(path_segments)

        seg_entry = processed_segments[seg_idx]
        seg_type = seg_entry[0]

        if seg_type == 'star_star':
            # ** matches zero or more path segments
            for i in range(path_idx, len(path_segments) + 1):
                if match(seg_idx + 1, i):
                    return True
            return False

        elif seg_type == 'segment':
            seg_data = seg_entry[1]
            if path_idx >= len(path_segments):
                return False
            path_seg = path_segments[path_idx]
            if match_segment(seg_data, path_seg):
                return match(seg_idx + 1, path_idx + 1)
            return False

        return False

    return match(0, 0)

