import re


def satisfies(version, rng):
    """Return True if `version` satisfies the range `rng`, else False.

    Versions are "MAJOR.MINOR.PATCH" optionally followed by "-PRERELEASE", where PRERELEASE is one or more
    dot-separated identifiers made of [0-9A-Za-z-]. MAJOR, MINOR, PATCH and purely numeric prerelease identifiers
    are non-negative integers without leading zeros ("0" is fine). Build metadata ("+...") is not allowed.
    An invalid version or range raises ValueError; the WHOLE range is validated even if an earlier part matches.

    Precedence (SemVer 2.0.0): compare MAJOR, MINOR, PATCH numerically. A version with a prerelease is lower than
    the same version without one. Prerelease identifiers are compared left to right: numeric ones numerically,
    alphanumeric ones in ASCII order, numeric always lower than alphanumeric, and if all shared identifiers are
    equal the version with fewer identifiers is lower.

    Range grammar: one or more comparator sets separated by "||" (whitespace around "||" is ignored). The range
    is satisfied if ANY set is satisfied. A set is one or more comparators separated by whitespace; it is
    satisfied if ALL its comparators are. An empty set (e.g. "1.0.0 ||") is invalid. Comparators, with no
    whitespace between operator and version:
        "V" or "=V"   equal to V
        ">V" ">=V" "<V" "<=V"
        "^V"          >=V and below the next "significant" version: < (MAJOR+1).0.0 if MAJOR > 0,
                      else < 0.(MINOR+1).0 if MINOR > 0, else < 0.0.(PATCH+1)
        "~V"          >=V and < MAJOR.(MINOR+1).0

    Prerelease rule: a version that HAS a prerelease satisfies a set only if, in addition, some comparator in that
    set names a version with the same MAJOR.MINOR.PATCH that also has a prerelease (for ^V and ~V the named
    version is V). Versions without a prerelease are not affected by this rule.
    """
    # Parse the version string
    ver = parse_version(version)

    # Parse the range string
    sets = parse_range(rng)

    # Check if any set satisfies the version
    for comparator_set in sets:
        if _satisfies_set(ver, comparator_set):
            return True
    return False


def parse_version(version_str):
    """Parse a version string into (major, minor, patch, prerelease) tuple.

    prerelease is a tuple of identifiers (int or str), or None if no prerelease.
    Raises ValueError if invalid.
    """
    # SemVer 2.0.0 regex
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?$'
    match = re.match(pattern, version_str)
    if not match:
        raise ValueError(f"Invalid version: {version_str}")

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    pre_str = match.group(4)

    if pre_str is not None:
        pre_ids = []
        for ident in pre_str.split('.'):
            if re.match(r'^\d+$', ident):
                pre_ids.append(int(ident))
            else:
                pre_ids.append(ident)
        prerelease = tuple(pre_ids)
    else:
        prerelease = None

    return (major, minor, patch, prerelease)


class _PreReleaseIdentifier:
    """Wrapper for prerelease identifiers to enable comparison.

    Numeric identifiers (int) are always less than alphanumeric identifiers (str).
    """
    def __init__(self, value):
        self.value = value

    def __lt__(self, other):
        if isinstance(other, _PreReleaseIdentifier):
            # Both are wrapped
            if isinstance(self.value, int) and isinstance(other.value, int):
                return self.value < other.value
            elif isinstance(self.value, int) and isinstance(other.value, str):
                # Numeric < alphanumeric
                return True
            elif isinstance(self.value, str) and isinstance(other.value, int):
                # Alphanumeric > numeric
                return False
            else:
                # Both str, compare as strings
                return self.value < other.value
        return NotImplemented

    def __eq__(self, other):
        if isinstance(other, _PreReleaseIdentifier):
            return self.value == other.value
        return NotImplemented

    def __le__(self, other):
        if isinstance(other, _PreReleaseIdentifier):
            return self.value == other.value or self < other
        return NotImplemented

    def __gt__(self, other):
        if isinstance(other, _PreReleaseIdentifier):
            return not (self <= other)
        return NotImplemented

    def __ge__(self, other):
        if isinstance(other, _PreReleaseIdentifier):
            return not (self < other)
        return NotImplemented

    def __repr__(self):
        return f"_PreReleaseIdentifier({self.value!r})"


def version_to_tuple(ver):
    """Convert parsed version to a comparable tuple."""
    major, minor, patch, prerelease = ver
    if prerelease is None:
        # A version without prerelease is greater than any version with prerelease of the same M.m.p
        # We represent this by using a special marker: (major, minor, patch, 1, ...) where 1 > 0 for prerelease
        return (major, minor, patch, 1)
    else:
        # Wrap prerelease identifiers in _PreReleaseIdentifier for proper comparison
        wrapped_pre = tuple(_PreReleaseIdentifier(id_) for id_ in prerelease)
        return (major, minor, patch, 0) + wrapped_pre


def compare_versions(v1, v2):
    """Compare two parsed versions. Returns -1, 0, or 1."""
    t1 = version_to_tuple(v1)
    t2 = version_to_tuple(v2)
    if t1 < t2:
        return -1
    elif t1 > t2:
        return 1
    else:
        return 0


def parse_range(rng_str):
    """Parse a range string into a list of comparator sets.

    Each set is a list of (operator, version) tuples.
    Raises ValueError if invalid.
    """
    rng_str = rng_str.strip()
    if not rng_str:
        raise ValueError("Empty range")

    # Split by ||
    or_parts = rng_str.split('||')
    sets = []
    for part in or_parts:
        part = part.strip()
        if not part:
            raise ValueError("Empty comparator set")
        comparators = parse_comparator_set(part)
        if not comparators:
            raise ValueError("Empty comparator set")
        sets.append(comparators)

    return sets


def parse_comparator_set(set_str):
    """Parse a comparator set string into a list of (operator, version) tuples."""
    set_str = set_str.strip()
    comparators = []

    # Split by whitespace
    tokens = set_str.split()
    for token in tokens:
        if not token:
            continue
        comparator = parse_comparator(token)
        comparators.append(comparator)

    return comparators


def parse_comparator(comp_str):
    """Parse a comparator string into (operator, version) tuple."""
    comp_str = comp_str.strip()
    if not comp_str:
        raise ValueError("Empty comparator")

    # Match operator and version
    pattern = r'^(>=|<=|>|<|=|~|\^)?(.+)$'
    match = re.match(pattern, comp_str)
    if not match:
        raise ValueError(f"Invalid comparator: {comp_str}")

    op = match.group(1)
    ver_str = match.group(2)

    if op is None:
        op = '='

    # Parse version
    ver = parse_version(ver_str)

    return (op, ver)


def _satisfies_set(ver, comparator_set):
    """Check if a version satisfies a comparator set."""
    # Check prerelease rule
    has_prerelease = ver[3] is not None

    if has_prerelease:
        # Check if any comparator in the set names a version with the same M.m.p and has a prerelease
        has_matching_prerelease_comparator = False
        for op, comp_ver in comparator_set:
            if comp_ver[3] is not None and comp_ver[0:3] == ver[0:3]:
                has_matching_prerelease_comparator = True
                break

        if not has_matching_prerelease_comparator:
            return False

    # Check all comparators
    for op, comp_ver in comparator_set:
        if not _check_comparator(ver, op, comp_ver):
            return False

    return True


def _check_comparator(ver, op, comp_ver):
    """Check if ver satisfies the comparator (op, comp_ver)."""
    cmp = compare_versions(ver, comp_ver)

    if op == '=':
        return cmp == 0
    elif op == '>':
        return cmp > 0
    elif op == '>=':
        return cmp >= 0
    elif op == '<':
        return cmp < 0
    elif op == '<=':
        return cmp <= 0
    elif op == '^':
        return _check_caret(ver, comp_ver)
    elif op == '~':
        return _check_tilde(ver, comp_ver)
    else:
        raise ValueError(f"Unknown operator: {op}")


def _check_caret(ver, comp_ver):
    """Check if ver satisfies ^comp_ver."""
    major, minor, patch, prerelease = comp_ver

    # Lower bound: >= comp_ver
    if compare_versions(ver, comp_ver) < 0:
        return False

    # Upper bound: < next significant version
    if major > 0:
        upper = (major + 1, 0, 0, None)
    elif minor > 0:
        upper = (major, minor + 1, 0, None)
    else:
        upper = (major, minor, patch + 1, None)

    if compare_versions(ver, upper) >= 0:
        return False

    return True


def _check_tilde(ver, comp_ver):
    """Check if ver satisfies ~comp_ver."""
    major, minor, patch, prerelease = comp_ver

    # Lower bound: >= comp_ver
    if compare_versions(ver, comp_ver) < 0:
        return False

    # Upper bound: < MAJOR.(MINOR+1).0
    upper = (major, minor + 1, 0, None)

    if compare_versions(ver, upper) >= 0:
        return False

    return True

