def glob_match(pattern, path):
    r"""Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    # Parse the pattern into segments
    segments = []
    current_segment = []
    i = 0
    n = len(pattern)

    while i < n:
        c = pattern[i]

        if c == '\\':
            if i + 1 >= n:
                raise ValueError("Trailing lone backslash in pattern")
            current_segment.append(('literal', pattern[i+1]))
            i += 2

        elif c == '?':
            current_segment.append(('any_char',))
            i += 1

        elif c == '*':
            if i + 1 < n and pattern[i+1] == '*':
                current_segment.append(('double_star',))
                i += 2
            else:
                current_segment.append(('any_string',))
                i += 1

        elif c == '[':
            # Parse char class
            i += 1
            negated = False
            if i < n and pattern[i] == '!':
                negated = True
                i += 1

            chars = set()
            if i < n and pattern[i] == ']':
                chars.add(']')
                i += 1

            while i < n and pattern[i] != ']':
                if pattern[i] == '\\' and i + 1 < n:
                    chars.add('\\')
                    i += 1
                    if i < n:
                        chars.add(pattern[i])
                        i += 1
                else:
                    if i + 2 < n and pattern[i+1] == '-' and pattern[i+2] != ']':
                        start_char = pattern[i]
                        end_char = pattern[i+2]
                        for code in range(ord(start_char), ord(end_char) + 1):
                            chars.add(chr(code))
                        i += 3
                    else:
                        chars.add(pattern[i])
                        i += 1

            if i >= n:
                raise ValueError("Unterminated '[' in pattern")
            i += 1
            current_segment.append(('char_class', chars, negated))

        elif c == '/':
            segments.append(current_segment)
            current_segment = []
            i += 1

        else:
            current_segment.append(('literal', c))
            i += 1

    segments.append(current_segment)

    # Resolve '**' segments
    resolved_segments = []
    for seg in segments:
        if len(seg) == 1 and seg[0][0] == 'double_star':
            resolved_segments.append(('segment_star',))
        else:
            resolved_segments.append(seg)

    # Split path into segments
    path_segments = path.split('/') if path else []

    m = len(path_segments)
    n_seg = len(resolved_segments)

    # DP table
    dp = [[False] * (n_seg + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n_seg + 1):
        if resolved_segments[j-1][0] == 'segment_star':
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = False

    for i in range(1, m + 1):
        for j in range(1, n_seg + 1):
            seg = resolved_segments[j-1]
            if seg[0] == 'segment_star':
                dp[i][j] = dp[i][j-1] or dp[i-1][j]
            else:
                if _segment_match(path_segments[i-1], seg):
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = False

    return dp[m][n_seg]


def _segment_match(path_seg, pattern_tokens):
    """Match a single path segment against a list of pattern tokens."""
    p_len = len(path_seg)
    t_len = len(pattern_tokens)

    dp = [[False] * (t_len + 1) for _ in range(p_len + 1)]
    dp[0][0] = True

    for j in range(1, t_len + 1):
        tok = pattern_tokens[j-1]
        if tok[0] in ('any_string', 'double_star'):
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = False

    for i in range(1, p_len + 1):
        for j in range(1, t_len + 1):
            tok = pattern_tokens[j-1]
            if tok[0] in ('any_string', 'double_star'):
                dp[i][j] = dp[i][j-1] or dp[i-1][j]
            elif tok[0] == 'any_char':
                dp[i][j] = dp[i-1][j-1]
            elif tok[0] == 'literal':
                if path_seg[i-1] == tok[1]:
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = False
            elif tok[0] == 'char_class':
                chars, negated = tok[1], tok[2]
                if negated:
                    if path_seg[i-1] not in chars and path_seg[i-1] != '/':
                        dp[i][j] = dp[i-1][j-1]
                    else:
                        dp[i][j] = False
                else:
                    if path_seg[i-1] in chars and path_seg[i-1] != '/':
                        dp[i][j] = dp[i-1][j-1]
                    else:
                        dp[i][j] = False
            else:
                dp[i][j] = False

    return dp[p_len][t_len]

